function draw() {
    // Clear background
    ctx.clearRect(0, 0, W, H);
    // Draw star field
    ctx.fillStyle = '#fff';
    stars.forEach(s => {
      ctx.globalAlpha = 0.5 + Math.random() * 0.5;
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.globalAlpha = 1;
    // Ship (triangle) with slight outline
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(ship.r, 0);
    ctx.lineTo(-ship.r, ship.r / 2);
    ctx.lineTo(-ship.r, -ship.r / 2);
    ctx.closePath();
    const shipGrad = ctx.createLinearGradient(0, -ship.r, 0, ship.r);
    shipGrad.addColorStop(0, '#00ffff');
    shipGrad.addColorStop(1, '#0066ff');
    ctx.fillStyle = shipGrad;
    ctx.fill();
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.restore();
    // Asteroids (rough circles with outline)
    ctx.fillStyle = '#555';
    ctx.strokeStyle = '#aaa';
    ctx.lineWidth = 2;
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    });
    // Fuel cells with glow
    fuels.forEach(f => {
      ctx.save();
      ctx.shadowColor = '#ff0';
      ctx.shadowBlur = 10;
      ctx.fillStyle = '#ff0';
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    });
    // Fuel bar
    ctx.fillStyle = '#0f0';
    ctx.fillRect(10, 10, ship.fuel, 8);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(10, 10, 100, 8);
  }

